/* ── helpers ─────────────────────────────────────────────────────────────── */
function makeArrow(len, color, rad) {
  rad = rad || 0.035;
  const g = new THREE.Group();
  const mat = new THREE.MeshStandardMaterial({ color: color, roughness: 0.45, metalness: 0.0 });
  const hl = Math.min(rad * 6, len * 0.3);
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(rad, rad, Math.max(0.01, len - 2 * hl), 10), mat);
  g.add(shaft);
  const cg = new THREE.ConeGeometry(rad * 2.6, hl, 14);
  const top = new THREE.Mesh(cg, mat); top.position.y = len / 2 - hl / 2; g.add(top);
  const bot = new THREE.Mesh(cg, mat); bot.position.y = -(len / 2 - hl / 2); bot.rotation.x = Math.PI; g.add(bot);
  return g;
}

function stripeTexture() {
  const cv = document.createElement('canvas'); cv.width = 256; cv.height = 256;
  const x = cv.getContext('2d');
  x.fillStyle = '#7A8A3C'; x.fillRect(0, 0, 256, 256);
  x.strokeStyle = '#1F2A12'; x.lineWidth = 3.5;
  for (let i = 0; i < 24; i++) {
    const px = (i + 0.5) * 256 / 24;
    x.beginPath(); x.moveTo(px, 0); x.lineTo(px, 256); x.stroke();
  }
  return new THREE.CanvasTexture(cv);
}

// Disc: outer group rotates about X (beam axis); inner mesh faces +X.
function makeDisc(xPos) {
  const outer = new THREE.Group(); outer.position.x = xPos;
  const inner = new THREE.Group(); inner.rotation.y = Math.PI / 2; outer.add(inner);
  const tex = stripeTexture();
  const faceMat = new THREE.MeshStandardMaterial({ map: tex, roughness: 0.5, metalness: 0.05, side: THREE.DoubleSide });
  const face = new THREE.Mesh(new THREE.CircleGeometry(1.0, 64), faceMat);
  inner.add(face);
  const rimMat = new THREE.MeshStandardMaterial({ color: GREY, roughness: 0.35, metalness: 0.35, side: THREE.DoubleSide });
  const rim = new THREE.Mesh(new THREE.CylinderGeometry(1.03, 1.03, 0.12, 64, 1, true), rimMat);
  rim.rotation.z = Math.PI / 2; outer.add(rim);
  const rimFace = new THREE.Mesh(new THREE.RingGeometry(0.98, 1.05, 64), rimMat);
  rimFace.rotation.y = Math.PI / 2; rimFace.position.x = 0.061; outer.add(rimFace);
  const rimFace2 = rimFace.clone(); rimFace2.position.x = -0.061; outer.add(rimFace2);
  scene.add(outer);
  return outer;
}

function greyLine(pts, color, dashed) {
  const g = new THREE.BufferGeometry().setFromPoints(pts);
  const m = dashed
    ? new THREE.LineDashedMaterial({ color: color, dashSize: 0.16, gapSize: 0.12 })
    : new THREE.LineBasicMaterial({ color: color });
  const l = new THREE.Line(g, m);
  if (dashed) l.computeLineDistances();
  scene.add(l);
  return l;
}

