<div style="font-size:10px;color:#666;line-height:1.35;margin-top:4px">
  Drag to orbit: the red double-headed arrows stand in the plane perpendicular to the beam, so turning the
  scene shows the polarization plane in 3D. Hover a component for a note.
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── Element spec (build exactly this) ───────────────────────────────────────
 bulb envelope      → SphereGeometry(0.55)           MeshBasic  #FFE45C
 filament           → Line (zig-zag)                 #B07A10
 screw base         → CylinderGeometry(.28,.24,.42)  MeshStandard #A8A8A8
 socket disc        → CylinderGeometry(.7,.75,.15)   MeshStandard #E6E6E6
 glow halo          → Sprite (radial-gradient canvas, NORMAL blend) r≈1.9
 unpolarized star   → 8 × makeArrow(0.5) #E8232A in YZ plane at x=-6.2
 beam ribbon (in)   → PlaneGeometry(9.1,0.9) in XZ   MeshBasic #F2D98C 62%
 beam ribbon (out)  → PlaneGeometry(3.4,0.9) in XZ   MeshBasic #F2D98C, opacity = cos²Δ
 polarizer          → CircleGeometry(1.0)+stripe CanvasTexture + rim Cylinder #BDBDBD
 polarized arrows   → 3 × makeArrow(1.4) vertical at x=-4.0,-3.3,-2.6
 sample tube        → open CylinderGeometry(.85,.85,4.4) + 2 domes MeshPhysical 40%
 tube liquid        → CylinderGeometry(.78,.78,4.2)  #BFD2BC 28%
 fill stub          → CylinderGeometry(.18,.18,.4)   #A8A8A8 at x=-1.2
 tube arrows        → 6 × makeArrow(1.3), rotation.x = -(i/5)·α
 analyzer           → same as polarizer, group.rotation.x = -analyzerAngle
 exit arrow         → makeArrow(2.0, r=.085), rotation.x = -α
 dashed reference   → LineDashedMaterial vertical at x=4.4
 α arc + head       → BufferGeometry arc r=1.1 in YZ + ConeGeometry head
 observer eye       → almond LineLoop (billboarded) + SphereGeometry pupil + 2 sight lines
 leader lines       → Line / QuadraticBezierCurve3, grey
────────────────────────────────────────────────────────────────────────────── */

const RED = 0xE8232A, BEAM = 0xF2D98C, GREY = 0xA8A8A8, INK = '#222222';

scene.add(new THREE.AmbientLight(0xffffff, 0.92));
const dl = new THREE.DirectionalLight(0xffffff, 0.55); dl.position.set(2, 6, 8); scene.add(dl);
const dl2 = new THREE.DirectionalLight(0xffffff, 0.3); dl2.position.set(-4, 2, -6); scene.add(dl2);

/* ── helpers ─────────────────────────────────────────────────────────────── */
function makeArrow(len, color, rad) {
  rad = rad || 0.04;
  const g = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({ color: color });
  const hl = Math.min(rad * 5.5, len * 0.3);
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(rad, rad, Math.max(0.01, len - 2 * hl), 12), mat);
  g.add(shaft);
  const cg = new THREE.ConeGeometry(rad * 2.7, hl, 16);
  const top = new THREE.Mesh(cg, mat); top.position.y = len / 2 - hl / 2; g.add(top);
  const bot = new THREE.Mesh(cg, mat); bot.position.y = -(len / 2 - hl / 2); bot.rotation.x = Math.PI; g.add(bot);
  return g;
}

function stripeTexture() {
  const cv = document.createElement('canvas'); cv.width = 256; cv.height = 256;
  const x = cv.getContext('2d');
  x.fillStyle = '#AFC25A'; x.fillRect(0, 0, 256, 256);
  x.strokeStyle = '#2B3512'; x.lineWidth = 4;
  for (let i = 0; i < 26; i++) {
    const px = (i + 0.5) * 256 / 26;
    x.beginPath(); x.moveTo(px, 0); x.lineTo(px, 256); x.stroke();
  }
  const t = new THREE.CanvasTexture(cv);
  t.anisotropy = 4;
  return t;
}

// Disc: outer group rotates about X (beam axis); inner mesh faces +X.
function makeDisc(xPos) {
  const outer = new THREE.Group(); outer.position.x = xPos;
  const inner = new THREE.Group(); inner.rotation.y = Math.PI / 2; outer.add(inner);
  const faceMat = new THREE.MeshBasicMaterial({ map: stripeTexture(), side: THREE.DoubleSide });
  const face = new THREE.Mesh(new THREE.CircleGeometry(1.0, 64), faceMat);
  inner.add(face);
  const rimMat = new THREE.MeshStandardMaterial({ color: 0xC4C4C4, roughness: 0.4, metalness: 0.25, side: THREE.DoubleSide });
  const rim = new THREE.Mesh(new THREE.CylinderGeometry(1.05, 1.05, 0.13, 64, 1, true), rimMat);
  rim.rotation.z = Math.PI / 2; outer.add(rim);
  const rimFace = new THREE.Mesh(new THREE.RingGeometry(0.99, 1.07, 64), rimMat);
  rimFace.rotation.y = Math.PI / 2; rimFace.position.x = 0.066; outer.add(rimFace);
  const rimFace2 = rimFace.clone(); rimFace2.position.x = -0.066; outer.add(rimFace2);
  scene.add(outer);
  return outer;
}

function greyLine(pts, color, dashed) {
  const g = new THREE.BufferGeometry().setFromPoints(pts);
  const m = dashed
    ? new THREE.LineDashedMaterial({ color: color, dashSize: 0.17, gapSize: 0.13 })
    : new THREE.LineBasicMaterial({ color: color });
  const l = new THREE.Line(g, m);
  if (dashed) l.computeLineDistances();
  scene.add(l);
  return l;
}

/* ── light source ────────────────────────────────────────────────────────── */
const sourceGroup = new THREE.Group(); scene.add(sourceGroup);

const bulb = new THREE.Mesh(
  new THREE.SphereGeometry(0.55, 32, 24),
  new THREE.MeshBasicMaterial({ color: 0xFFE45C })
);
bulb.position.set(-7.4, 0.5, 0); sourceGroup.add(bulb);

const filPts = [];
for (let i = 0; i <= 8; i++) filPts.push(new THREE.Vector3(-7.4 + (i % 2 ? 0.11 : -0.11), 0.22 + i * 0.05, 0));
sourceGroup.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(filPts),
  new THREE.LineBasicMaterial({ color: 0xB07A10 })));

const baseMat = new THREE.MeshStandardMaterial({ color: GREY, roughness: 0.4, metalness: 0.45 });
const screw = new THREE.Mesh(new THREE.CylinderGeometry(0.28, 0.24, 0.42, 20), baseMat);
screw.position.set(-7.4, -0.12, 0); sourceGroup.add(screw);
const socket = new THREE.Mesh(new THREE.CylinderGeometry(0.7, 0.78, 0.16, 32),
  new THREE.MeshStandardMaterial({ color: 0xEAEAEA, roughness: 0.5 }));
socket.position.set(-7.4, -0.42, 0); sourceGroup.add(socket);

// glow sprite — NORMAL blending so it is visible on the white background
(function () {
  const cv = document.createElement('canvas'); cv.width = 160; cv.height = 160;
  const ctx = cv.getContext('2d');
  const g = ctx.createRadialGradient(80, 80, 6, 80, 80, 80);
  g.addColorStop(0, 'rgba(255,242,140,0.85)');
  g.addColorStop(0.35, 'rgba(255,240,130,0.45)');
  g.addColorStop(0.7, 'rgba(255,240,150,0.14)');
  g.addColorStop(1, 'rgba(255,245,180,0)');
  ctx.fillStyle = g; ctx.fillRect(0, 0, 160, 160);
  const sp = new THREE.Sprite(new THREE.SpriteMaterial({
    map: new THREE.CanvasTexture(cv), transparent: true, opacity: 0.95, depthWrite: false
  }));
  sp.scale.set(3.8, 3.8, 1); sp.position.set(-7.4, 0.45, -0.05); sourceGroup.add(sp);
})();

registerInteractive(bulb, {
  title: 'Light source',
  tooltip: 'Unpolarized light source',
