  <input type="range" id="sampleRotation" min="-60" max="60" step="1" value="30">
</label>
<label>Analyzer rotation (&deg;): <b id="valAnalyzer">0</b>
  <input type="range" id="analyzerAngle" min="-90" max="90" step="1" value="0">
</label>
<div style="font-size:11px;line-height:1.4">
  Transmitted intensity&nbsp;=&nbsp;cos<sup>2</sup>(analyzer &minus; &alpha;)&nbsp;=&nbsp;<b id="valTrans">100%</b>
</div>
<button id="btnPulse">▶ Send a pulse of light</button>
<div style="display:flex;gap:4px;margin-top:4px">
  <button id="btnPrev">◀ Prev</button>
  <button id="btnNext">Next ▶</button>
</div>
<div id="narration" style="font-size:11px;line-height:1.4;margin-top:2px"></div>
<div style="font-size:10px;color:#666;line-height:1.35;margin-top:4px">
  Drag to orbit: the red double-headed arrows stand in the plane perpendicular to the beam, so turning the
  scene shows the polarization plane in 3D. Hover a component for a note.
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── Element spec (build exactly this) ───────────────────────────────────────
 bulb envelope      → SphereGeometry(0.55)           MeshBasic  #FFE45C
 filament           → Line (zig-zag)                 #B07A10
 screw base         → CylinderGeometry(.28,.24,.42)  MeshStandard #A8A8A8
 socket disc        → CylinderGeometry(.7,.75,.15)   MeshStandard #E6E6E6
 glow halo          → Sprite (radial-gradient canvas, NORMAL blend) r≈1.9
 unpolarized star   → 8 × makeArrow(0.5) #E8232A in YZ plane at x=-6.2
 beam ribbon (in)   → PlaneGeometry(9.1,0.9) in XZ   MeshBasic #F2D98C 62%
 beam ribbon (out)  → PlaneGeometry(3.4,0.9) in XZ   MeshBasic #F2D98C, opacity = cos²Δ
 polarizer          → CircleGeometry(1.0)+stripe CanvasTexture + rim Cylinder #BDBDBD
 polarized arrows   → 3 × makeArrow(1.4) vertical at x=-4.0,-3.3,-2.6
 sample tube        → open CylinderGeometry(.85,.85,4.4) + 2 domes MeshPhysical 40%
 tube liquid        → CylinderGeometry(.78,.78,4.2)  #BFD2BC 28%
 fill stub          → CylinderGeometry(.18,.18,.4)   #A8A8A8 at x=-1.2
 tube arrows        → 6 × makeArrow(1.3), rotation.x = -(i/5)·α
 analyzer           → same as polarizer, group.rotation.x = -analyzerAngle
 exit arrow         → makeArrow(2.0, r=.085), rotation.x = -α
 dashed reference   → LineDashedMaterial vertical at x=4.4
 α arc + head       → BufferGeometry arc r=1.1 in YZ + ConeGeometry head
 observer eye       → almond LineLoop (billboarded) + SphereGeometry pupil + 2 sight lines
 leader lines       → Line / QuadraticBezierCurve3, grey
────────────────────────────────────────────────────────────────────────────── */

const RED = 0xE8232A, BEAM = 0xF2D98C, GREY = 0xA8A8A8, INK = '#222222';

scene.add(new THREE.AmbientLight(0xffffff, 0.92));
const dl = new THREE.DirectionalLight(0xffffff, 0.55); dl.position.set(2, 6, 8); scene.add(dl);
const dl2 = new THREE.DirectionalLight(0xffffff, 0.3); dl2.position.set(-4, 2, -6); scene.add(dl2);

/* ── helpers ─────────────────────────────────────────────────────────────── */
function makeArrow(len, color, rad) {
  rad = rad || 0.04;
  const g = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({ color: color });
  const hl = Math.min(rad * 5.5, len * 0.3);
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(rad, rad, Math.max(0.01, len - 2 * hl), 12), mat);
  g.add(shaft);
  const cg = new THREE.ConeGeometry(rad * 2.7, hl, 16);
  const top = new THREE.Mesh(cg, mat); top.position.y = len / 2 - hl / 2; g.add(top);
  const bot = new THREE.Mesh(cg, mat); bot.position.y = -(len / 2 - hl / 2); bot.rotation.x = Math.PI; g.add(bot);
  return g;
}

function stripeTexture() {
  const cv = document.createElement('canvas'); cv.width = 256; cv.height = 256;
  const x = cv.getContext('2d');
  x.fillStyle = '#AFC25A'; x.fillRect(0, 0, 256, 256);
  x.strokeStyle = '#2B3512'; x.lineWidth = 4;
  for (let i = 0; i < 26; i++) {
    const px = (i + 0.5) * 256 / 26;
    x.beginPath(); x.moveTo(px, 0); x.lineTo(px, 256); x.stroke();
  }
  const t = new THREE.CanvasTexture(cv);
  t.anisotropy = 4;
  return t;
}

// Disc: outer group rotates about X (beam axis); inner mesh faces +X.
function makeDisc(xPos) {
  const outer = new THREE.Group(); outer.position.x = xPos;
  const inner = new THREE.Group(); inner.rotation.y = Math.PI / 2; outer.add(inner);
  const faceMat = new THREE.MeshBasicMaterial({ map: stripeTexture(), side: THREE.DoubleSide });
  const face = new THREE.Mesh(new THREE.CircleGeometry(1.0, 64), faceMat);
  inner.add(face);
  const rimMat = new THREE.MeshStandardMaterial({ color: 0xC4C4C4, roughness: 0.4, metalness: 0.25, side: THREE.DoubleSide });
  const rim = new THREE.Mesh(new THREE.CylinderGeometry(1.05, 1.05, 0.13, 64, 1, true), rimMat);
  rim.rotation.z = Math.PI / 2; outer.add(rim);
  const rimFace = new THREE.Mesh(new THREE.RingGeometry(0.99, 1.07, 64), rimMat);
  rimFace.rotation.y = Math.PI / 2; rimFace.position.x = 0.066; outer.add(rimFace);
  const rimFace2 = rimFace.clone(); rimFace2.position.x = -0.066; outer.add(rimFace2);
  scene.add(outer);
  return outer;
}

function greyLine(pts, color, dashed) {
  const g = new THREE.BufferGeometry().setFromPoints(pts);
  const m = dashed
    ? new THREE.LineDashedMaterial({ color: color, dashSize: 0.17, gapSize: 0.13 })
    : new THREE.LineBasicMaterial({ color: color });
  const l = new THREE.Line(g, m);
  if (dashed) l.computeLineDistances();
  scene.add(l);
  return l;
}

/* ── light source ────────────────────────────────────────────────────────── */
const sourceGroup = new THREE.Group(); scene.add(sourceGroup);

const bulb = new THREE.Mesh(
  new THREE.SphereGeometry(0.55, 32, 24),
  new THREE.MeshBasicMaterial({ color: 0xFFE45C })
);
bulb.position.set(-7.4, 0.5, 0); sourceGroup.add(bulb);

const filPts = [];
for (let i = 0; i <= 8; i++) filPts.push(new THREE.Vector3(-7.4 + (i % 2 ? 0.11 : -0.11), 0.22 + i * 0.05, 0));
sourceGroup.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(filPts),
  new THREE.LineBasicMaterial({ color: 0xB07A10 })));

const baseMat = new THREE.MeshStandardMaterial({ color: GREY, roughness: 0.4, metalness: 0.45 });
const screw = new THREE.Mesh(new THREE.CylinderGeometry(0.28, 0.24, 0.42, 20), baseMat);
screw.position.set(-7.4, -0.12, 0); sourceGroup.add(screw);
const socket = new THREE.Mesh(new THREE.CylinderGeometry(0.7, 0.78, 0.16, 32),
  new THREE.MeshStandardMaterial({ color: 0xEAEAEA, roughness: 0.5 }));
socket.position.set(-7.4, -0.42, 0); sourceGroup.add(socket);

// glow sprite — NORMAL blending so it is visible on the white background
(function () {
  const cv = document.createElement('canvas'); cv.width = 160; cv.height = 160;
  const ctx = cv.getContext('2d');
  const g = ctx.createRadialGradient(80, 80, 6, 80, 80, 80);
  g.addColorStop(0, 'rgba(255,242,140,0.85)');
  g.addColorStop(0.35, 'rgba(255,240,130,0.45)');
  g.addColorStop(0.7, 'rgba(255,240,150,0.14)');
  g.addColorStop(1, 'rgba(255,245,180,0)');
  ctx.fillStyle = g; ctx.fillRect(0, 0, 160, 160);
  const sp = new THREE.Sprite(new THREE.SpriteMaterial({
    map: new THREE.CanvasTexture(cv), transparent: true, opacity: 0.95, depthWrite: false
  }));
  sp.scale.set(3.8, 3.8, 1); sp.position.set(-7.4, 0.45, -0.05); sourceGroup.add(sp);
})();

registerInteractive(bulb, {
  title: 'Light source',
  tooltip: 'Unpolarized light source',
  body: 'An incandescent bulb emits light whose electric field oscillates in every possible orientation perpendicular to the direction of travel — it is unpolarized.'
});

/* ── unpolarized arrow star ──────────────────────────────────────────────── */
const starGroup = new THREE.Group(); starGroup.position.set(-6.2, 0.3, 0); scene.add(starGroup);
[4, 27, 51, 74, 98, 121, 145, 166].forEach(function (a, i) {
  const ar = makeArrow(0.5, RED, 0.032);
  ar.rotation.x = THREE.MathUtils.degToRad(a);
  if (i % 3 === 1) ar.rotation.z = THREE.MathUtils.degToRad(i % 2 ? 24 : -24);
  starGroup.add(ar);
});
registerInteractive(starGroup, {
  title: 'Unpolarized light',
  tooltip: 'Electric field in all orientations',
  body: 'Each red double-headed arrow is one plane of oscillation. Pointing in all directions at once means the beam has no preferred polarization plane.'
});

/* ── beam ribbons (flat sheets in the XZ plane) ──────────────────────────── */
function ribbon(x0, x1, opacity) {
  const m = new THREE.Mesh(
    new THREE.PlaneGeometry(x1 - x0, 0.9),
    new THREE.MeshBasicMaterial({ color: BEAM, transparent: true, opacity: opacity, side: THREE.DoubleSide, depthWrite: false })
  );
  m.rotation.x = -Math.PI / 2;
  m.position.set((x0 + x1) / 2, 0, 0);
  scene.add(m);
  return m;
}
const ribbonIn = ribbon(-6.5, 2.6, 0.62);
const ribbonOut = ribbon(2.6, 6.0, 0.62);

/* ── polarizer ───────────────────────────────────────────────────────────── */
const polarizer = makeDisc(-4.6);
registerInteractive(polarizer, {
  title: 'Polarizer',
  tooltip: 'Transmits only one plane',
  body: 'The striped filter transmits only the component of the electric field parallel to its vertical transmission axis. Downstream, every arrow lies in one vertical plane: the light is plane-polarized.'
});

/* ── polarized (vertical) arrows ─────────────────────────────────────────── */
[-4.0, -3.3, -2.6].forEach(function (x) {
  const a = makeArrow(1.4, RED, 0.045);
  a.position.x = x; scene.add(a);
});

/* ── sample tube ─────────────────────────────────────────────────────────── */
const tube = new THREE.Group(); tube.position.x = -0.6; scene.add(tube);
const glassMat = new THREE.MeshPhysicalMaterial({
  color: 0xD6DED2, transparent: true, opacity: 0.4, roughness: 0.08,
  metalness: 0.0, clearcoat: 1.0, side: THREE.DoubleSide, depthWrite: false
});
const body = new THREE.Mesh(new THREE.CylinderGeometry(0.85, 0.85, 4.4, 48, 1, true), glassMat);
body.rotation.z = Math.PI / 2; tube.add(body);
[-1, 1].forEach(function (s) {
  const dome = new THREE.Mesh(new THREE.SphereGeometry(0.85, 40, 24, 0, Math.PI * 2, 0, Math.PI / 2), glassMat);
  dome.rotation.z = -s * Math.PI / 2;
  dome.position.x = s * 2.2; tube.add(dome);
});
const liquid = new THREE.Mesh(new THREE.CylinderGeometry(0.78, 0.78, 4.2, 40, 1, true),
  new THREE.MeshPhysicalMaterial({
    color: 0xBFD2BC, transparent: true, opacity: 0.28, roughness: 0.15,
    side: THREE.DoubleSide, depthWrite: false
  }));
liquid.rotation.z = Math.PI / 2; tube.add(liquid);
const stub = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.18, 0.4, 20),
  new THREE.MeshStandardMaterial({ color: GREY, roughness: 0.35, metalness: 0.4 }));
stub.position.set(-0.6, 0.98, 0); tube.add(stub);
registerInteractive(body, {
  title: 'Sample tube containing organic molecules',
  tooltip: 'Optically active sample',
  body: 'A chiral (optically active) sample rotates the plane of polarization progressively as the light travels through it. The rotation grows with concentration and path length.'
});

/* ── arrows inside the tube ──────────────────────────────────────────────── */
const tubeArrows = [];
[-2.6, -1.9, -1.2, -0.5, 0.2, 0.9].forEach(function (x) {
  const a = makeArrow(1.3, RED, 0.048);
  a.position.x = x; scene.add(a); tubeArrows.push(a);
});

/* ── analyzer ────────────────────────────────────────────────────────────── */
const analyzer = makeDisc(2.6);
registerInteractive(analyzer, {
  title: 'Analyzer',
  tooltip: 'Rotate to measure α',
  body: 'A second polarizing disc on a calibrated dial. The observer turns it until the transmitted light is brightest; the dial reading is the observed rotation α.'
});

/* ── exit region: heavy arrow, dashed reference, α arc ───────────────────── */
const exitArrow = makeArrow(2.0, RED, 0.085);
exitArrow.position.x = 4.4; scene.add(exitArrow);
greyLine([new THREE.Vector3(4.4, -1.35, 0), new THREE.Vector3(4.4, 1.5, 0)], 0x666666, true);

const arcMat = new THREE.LineBasicMaterial({ color: 0x222222 });
const arcLine = new THREE.Line(new THREE.BufferGeometry(), arcMat); scene.add(arcLine);
const arcHead = new THREE.Mesh(new THREE.ConeGeometry(0.075, 0.22, 14),
  new THREE.MeshBasicMaterial({ color: 0x222222 }));
scene.add(arcHead);
const _upV = new THREE.Vector3(0, 1, 0), _tanV = new THREE.Vector3();

function rebuildArc(rad) {
  const pts = [], n = 48;
  for (let i = 0; i <= n; i++) {
    const t = rad * i / n;
    pts.push(new THREE.Vector3(4.4, 1.1 * Math.cos(t), -1.1 * Math.sin(t)));
  }
  const old = arcLine.geometry;
  arcLine.geometry = new THREE.BufferGeometry().setFromPoints(pts);
  if (old) old.dispose();
  const show = Math.abs(rad) > 0.06;
  arcLine.visible = show; arcHead.visible = show;
  if (show) {
    const sgn = Math.sign(rad);
    arcHead.position.set(4.4, 1.1 * Math.cos(rad), -1.1 * Math.sin(rad));
    _tanV.set(0, -Math.sin(rad) * sgn, -Math.cos(rad) * sgn).normalize();
    arcHead.quaternion.setFromUnitVectors(_upV, _tanV);
  }
}

/* ── observer eye (billboarded pictogram) ────────────────────────────────── */
const eyeGroup = new THREE.Group(); eyeGroup.position.set(7.5, -0.15, 0); scene.add(eyeGroup);
(function () {
  const pts = [];
  for (let i = 0; i <= 26; i++) { const t = -1 + 2 * i / 26; pts.push(new THREE.Vector3(0.68 * t, 0.42 * (1 - t * t), 0)); }
  for (let i = 0; i <= 26; i++) { const t = 1 - 2 * i / 26; pts.push(new THREE.Vector3(0.68 * t, -0.42 * (1 - t * t), 0)); }
  eyeGroup.add(new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineBasicMaterial({ color: 0x333333 })));
  const iris = new THREE.Mesh(new THREE.CircleGeometry(0.2, 28),
    new THREE.MeshBasicMaterial({ color: 0x1b1b1b, side: THREE.DoubleSide }));
  iris.position.z = 0.02; eyeGroup.add(iris);
  registerInteractive(iris, {
    title: 'Observer',
    tooltip: 'Looks back along the beam',
    body: 'Looking back toward the source, the observer sees the beam brighten and dim as the analyzer turns. Maximum brightness means the analyzer axis matches the exit polarization plane.'
  });
})();
greyLine([new THREE.Vector3(5.6, 0.12, 0), new THREE.Vector3(6.85, 0.05, 0)], 0x888888, false);
greyLine([new THREE.Vector3(5.6, -0.5, 0), new THREE.Vector3(6.85, -0.4, 0)], 0x888888, false);

/* ── travelling pulse (hidden until enabled) ─────────────────────────────── */
const pulseSeg = new THREE.Mesh(new THREE.PlaneGeometry(1.0, 0.92),
  new THREE.MeshBasicMaterial({
    color: 0xFFD24A, transparent: true, opacity: 0.9,
    side: THREE.DoubleSide, depthWrite: false
  }));
pulseSeg.rotation.x = -Math.PI / 2; pulseSeg.visible = false; scene.add(pulseSeg);
const pulseArrow = makeArrow(1.3, 0xFF4A3C, 0.06);
pulseArrow.visible = false; scene.add(pulseArrow);

/* ── leader lines ────────────────────────────────────────────────────────── */
(function () {
  const curve = new THREE.QuadraticBezierCurve3(
    new THREE.Vector3(-0.7, -2.15, 0.25),
    new THREE.Vector3(-1.35, -1.55, 0.3),
    new THREE.Vector3(-1.0, -0.8, 0.45)
  );
  greyLine(curve.getPoints(30), 0x444444, false);
  greyLine([new THREE.Vector3(-7.15, 1.95, 0), new THREE.Vector3(-6.6, 0.85, 0)], 0x444444, false);
  greyLine([new THREE.Vector3(-3.3, 2.05, 0), new THREE.Vector3(-3.3, 0.95, 0)], 0x444444, false);
})();

/* ── camera (perspective, near-side view across the optical axis) ────────── */
setCameraView({ projection: 'perspective', azimuthDeg: 64, elevationDeg: 16, rollDeg: 0, heightFraction: 0.94 });
controls.minPolarAngle = 0.3;
controls.maxPolarAngle = Math.PI / 2 + 0.22;
document.getElementById('btnReset').style.display = '';

/* ── labels (font size compensated for the perspective view distance) ────── */
const _camDist = camera.position.distanceTo(controls.target);
const K = Math.max(1, _camDist / 8);
const FS = function (px) { return (px * K).toFixed(1) + 'px'; };

addLabel('Unpolarized<br>light', new THREE.Vector3(-7.6, 2.55, 0), { fontSize: FS(14), color: INK });
addLabel('Light<br>source', new THREE.Vector3(-7.5, -1.45, 0), { fontSize: FS(14), color: INK });
addLabel('Polarizer', new THREE.Vector3(-4.75, -1.75, 0), { fontSize: FS(14), color: INK });
addLabel('Polarized<br>light', new THREE.Vector3(-3.3, 2.65, 0), { fontSize: FS(14), color: INK });
addLabel('Sample tube containing<br>organic molecules', new THREE.Vector3(-0.6, -2.55, 0.25), { fontSize: FS(14), color: INK });
addLabel('Analyzer', new THREE.Vector3(2.6, -1.9, 0), { fontSize: FS(14), color: INK });
addLabel('Observer', new THREE.Vector3(7.6, -1.25, 0), { fontSize: FS(14), color: INK });
const alphaLbl = addLabel('<i>&alpha;</i>', new THREE.Vector3(4.4, 1.5, -0.8),
  { fontSize: FS(18), color: INK, bold: true });

/* ── state + update ──────────────────────────────────────────────────────── */
const sSlider = document.getElementById('sampleRotation');
const aSlider = document.getElementById('analyzerAngle');
const sVal = document.getElementById('valSample');
const aVal = document.getElementById('valAnalyzer');
const tVal = document.getElementById('valTrans');
let sampleDeg = +sSlider.value, analyzerDeg = +aSlider.value;

function update() {
  const s = THREE.MathUtils.degToRad(sampleDeg);
  const a = THREE.MathUtils.degToRad(analyzerDeg);
  for (let i = 0; i < tubeArrows.length; i++) tubeArrows[i].rotation.x = -s * (i / (tubeArrows.length - 1));
  analyzer.rotation.x = -a;
  exitArrow.rotation.x = -s;
  const trans = Math.pow(Math.cos(a - s), 2);
  ribbonOut.material.opacity = 0.08 + 0.56 * trans;
  exitArrow.traverse(function (o) { if (o.material) { o.material.transparent = true; o.material.opacity = 0.32 + 0.68 * trans; } });
  rebuildArc(s);
  sVal.textContent = sampleDeg.toFixed(0);
  aVal.textContent = analyzerDeg.toFixed(0);
  tVal.textContent = Math.round(trans * 100) + '%';
  alphaLbl.pos.set(4.4, 1.45 * Math.cos(s / 2) + 0.12, -1.45 * Math.sin(s / 2) - 0.12 * Math.sign(s || 1));
}
sSlider.addEventListener('input', function () { sampleDeg = +sSlider.value; tween = null; update(); });
aSlider.addEventListener('input', function () { analyzerDeg = +aSlider.value; tween = null; update(); });

/* ── pulse animation ─────────────────────────────────────────────────────── */
const btnPulse = document.getElementById('btnPulse');
let pulseOn = false, pulseT = 0;
btnPulse.addEventListener('click', function () {
  pulseOn = !pulseOn;
  btnPulse.classList.toggle('active', pulseOn);
  btnPulse.textContent = pulseOn ? '■ Stop pulse' : '▶ Send a pulse of light';
  pulseSeg.visible = pulseOn; pulseArrow.visible = pulseOn;
  if (pulseOn) pulseT = 0;
});

/* ── demo steps ──────────────────────────────────────────────────────────── */
const steps = [
  { title: 'Unpolarized light leaves the source', narration: 'The bulb emits light whose electric field oscillates in every orientation, shown as red double-headed arrows pointing in many directions.', state: { sampleRotation: 0, analyzerAngle: 0 } },
  { title: 'Polarizer selects one plane', narration: 'After the striped polarizer only the vertical plane survives; the arrows between polarizer and tube are all vertical.', state: { sampleRotation: 0, analyzerAngle: 0 } },
  { title: 'An inactive sample changes nothing', narration: 'With optical rotation set to zero, the arrows stay vertical through the whole tube and α = 0°; the analyzer at 0° passes the beam fully.', state: { sampleRotation: 0, analyzerAngle: 0 } },
  { title: 'A chiral sample rotates the plane', narration: 'Set a positive rotation: the arrows tip further and further as they travel through the tube, leaving at +30° from vertical.', state: { sampleRotation: 30, analyzerAngle: 0 } },
  { title: 'The observer finds α', narration: 'Rotating the analyzer to +30° restores maximum brightness — the angle read off the dashed reference line is α, the rotation imposed by the sample.', state: { sampleRotation: 30, analyzerAngle: 30 } },
  { title: 'Opposite enantiomer, opposite sign', narration: 'A rotation of −30° tips the arrows the other way; the analyzer must now be turned to −30°, showing that α carries a sign.', state: { sampleRotation: -30, analyzerAngle: -30 } }
];
const narr = document.getElementById('narration');
let stepIdx = -1, tween = null;

function goToStep(i) {
  stepIdx = ((i % steps.length) + steps.length) % steps.length;
  const st = steps[stepIdx];
  narr.innerHTML = '<b>' + (stepIdx + 1) + '/' + steps.length + ' · ' + st.title + '</b><br>' + st.narration;
  tween = {
    t: 0,
    from: { s: sampleDeg, a: analyzerDeg },
    to: { s: st.state.sampleRotation, a: st.state.analyzerAngle }
  };
}
document.getElementById('btnNext').addEventListener('click', function () { goToStep(stepIdx + 1); });
document.getElementById('btnPrev').addEventListener('click', function () { goToStep(stepIdx - 1); });
update();
goToStep(3);

/* ── own update loop (scaffold owns rendering) ───────────────────────────── */
const _clock = new THREE.Clock();
function tick() {
  requestAnimationFrame(tick);
  const dt = Math.min(0.05, _clock.getDelta());

  eyeGroup.lookAt(camera.position);

  if (tween) {
    tween.t += dt / 0.8;
    const k = tween.t >= 1 ? 1 : tween.t * tween.t * (3 - 2 * tween.t);
    sampleDeg = THREE.MathUtils.lerp(tween.from.s, tween.to.s, k);
    analyzerDeg = THREE.MathUtils.lerp(tween.from.a, tween.to.a, k);
    sSlider.value = sampleDeg.toFixed(0);
    aSlider.value = analyzerDeg.toFixed(0);
    update();
    if (tween.t >= 1) tween = null;
  }

  if (pulseOn) {
    pulseT += dt * 0.22;
    if (pulseT > 1) pulseT -= 1;
    const x = THREE.MathUtils.lerp(-6.5, 6.0, pulseT);
    pulseSeg.position.x = x;
    pulseArrow.position.x = x;
    const s = THREE.MathUtils.degToRad(sampleDeg);
    let rot;
    if (x < -4.6) rot = Math.random() * Math.PI;                       // unpolarized
    else if (x < -2.8) rot = 0;                                        // plane-polarized
    else if (x < 1.6) rot = -s * (x + 2.8) / 4.4;                      // twisting in sample
    else rot = -s;                                                     // fixed after tube
    pulseArrow.rotation.x = rot;
    const trans = Math.pow(Math.cos(THREE.MathUtils.degToRad(analyzerDeg) - s), 2);
    const dim = x > 2.6 ? trans : 1;
    pulseSeg.material.opacity = 0.9 * dim;
    pulseArrow.traverse(function (o) { if (o.material) { o.material.transparent = true; o.material.opacity = 0.25 + 0.75 * dim; } });
  }
}
tick();
// @FIGURE_CODE_END

