/* ── camera (perspective; azimuth keeps the beam horizontal while still
       showing the YZ polarization plane and the α arc face-enough-on) ────── */
const FIG_VIEW = { projection: 'perspective', azimuthDeg: 55, elevationDeg: 18, rollDeg: 0, heightFraction: 0.9 };
const OBS_VIEW = { projection: 'perspective', azimuthDeg: 3, elevationDeg: 7, rollDeg: 0, target: [3.0, 0, 0], heightFraction: 0.82 };
setCameraView(FIG_VIEW);
controls.minPolarAngle = 0.25;
controls.maxPolarAngle = Math.PI / 2 + 0.22;

/* ── labels (font size compensated for the perspective view distance) ────── */
