const K = Math.max(1, _camDist / 8);
const FS = function (px) { return (px * K).toFixed(1) + 'px'; };

addLabel('Unpolarized<br>light', new THREE.Vector3(-7.5, 2.7, 0), { fontSize: FS(14), color: INK });
addLabel('Light<br>source', new THREE.Vector3(-7.45, -1.55, 0), { fontSize: FS(14), color: INK });
